import fcntl,os,pathlib,threading,time
def collect(path):
    path=pathlib.Path(path);fd=os.open(path,os.O_RDWR|os.O_CREAT,0o600);rows=[]
    try:
        for i in range(101):
            queued=i>=99;ready=threading.Event();holder=None
            if queued:
                def hold():
                    other=os.open(path,os.O_RDWR)
                    try:fcntl.flock(other,fcntl.LOCK_EX);ready.set();time.sleep(.05)
                    finally:fcntl.flock(other,fcntl.LOCK_UN);os.close(other)
                holder=threading.Thread(target=hold);holder.start();assert ready.wait(2)
            begin=time.monotonic_ns();fcntl.flock(fd,fcntl.LOCK_EX)
            try:os.pwrite(fd,b'X'*4096,0);os.fsync(fd)
            finally:fcntl.flock(fd,fcntl.LOCK_UN)
            rows.append({'latency_ns':time.monotonic_ns()-begin,'phase':'queued'if queued else'uncontended','operation':'pwrite_fsync','block_bytes':4096,'queued_on_flock':queued})
            if holder:holder.join(timeout=2);assert not holder.is_alive()
        return rows
    finally:os.close(fd)

